#include <vector>
#include <algorithm>
#include <climits>

class Solution {
public:
    int minCapacityBox(std::vector<int>& packages, std::vector<int>& boxes) {
        int maxP = 0;
        for (int p : packages) maxP = std::max(maxP, p);
        int best = INT_MAX;
        for (int b : boxes) {
            if (b >= maxP) best = std::min(best, b);
        }
        return best == INT_MAX ? -1 : best;
    }
};

class Solution {
    public int minCapacityBox(int[] packages, int[] boxes) {
        int maxP = 0;
        for (int p : packages) maxP = Math.max(maxP, p);
        int best = Integer.MAX_VALUE;
        for (int b : boxes) {
            if (b >= maxP) best = Math.min(best, b);
        }
        return best == Integer.MAX_VALUE ? -1 : best;
    }
}

function minCapacityBox(packages, boxes) {
    let maxP = 0;
    for (const p of packages) if (p > maxP) maxP = p;
    let best = Infinity;
    for (const b of boxes) {
        if (b >= maxP && b < best) best = b;
    }
    return best === Infinity ? -1 : best;
}
